// 同一真实session的批量只读门：逐项对照已签收叶DTO，保字段序、当前玩家隐私和恢复来源。
#include "resident/kernel/boundary_dispatch.hpp"
#include "resident/storage/common_codec.hpp"
#include <algorithm>
#include <cassert>
#include <fstream>
#include <iostream>
using namespace hanmo::resident;
namespace {
using V=BoundaryValue;using D=V::Dict;using A=V::Array;
// 只读取已存在的原GD夹具；无默认世界、隐式身份或未验证字段回退。
V read(const std::string& path){std::ifstream f(path);assert(f.good());std::string bytes((std::istreambuf_iterator<char>(f)),{});auto value=parse_boundary_json(bytes);assert(value.ok);return std::move(value.value);}
V object(std::initializer_list<std::pair<std::string,V>> fields){return V{D{fields}};}
std::string text(const V& value,const std::string& key){return boundary::get_string(value,key,"test");}
template<class T>T checked(Outcome<T> result){if(!result.ok){std::cerr<<result.error.original.code<<":"<<result.error.original.path<<"\n";std::abort();}return std::move(result.value);}
void require(Status value){if(!value.ok){std::cerr<<value.error.original.code<<":"<<value.error.original.path<<"\n";std::abort();}}
bool same(const WorldIdentity& a,const WorldIdentity& b){return a.world_id==b.world_id&&a.execution_epoch==b.execution_epoch&&a.revision==b.revision&&a.tick==b.tick;}
void exact(const V& expected,const V& actual){auto diff=compare_boundary(expected,actual);if(!diff.exact()){auto failure=diff.value_difference?diff.value_difference:diff.order_difference;std::cerr<<failure->path<<":"<<failure->reason<<"\n";std::abort();}}
LiveOperation request(const WorldIdentity& source,const std::string& id,V args=object({})){return {LiveOperationKind::query,source,object({{"query_id",V{id}},{"args",std::move(args)}})};}
// 原子读取的发起和完成身份须相同，单独叶对照也不借新revision重绑。
V query(ResidentReplaySession& session,const std::string& id,V args=object({})){auto before=checked(session.identity());auto result=checked(session.execute_live(request(before,id,std::move(args))));assert(same(before,result.source_identity)&&same(before,result.current_identity));return std::move(result.result);}
// 普通负报价保原code及完整字段；测试不从按钮状态推断权限或省掉拒绝值。
V preview(ResidentReplaySession& session,const std::string& actor,const std::string& kind,V params){auto before=checked(session.identity());auto result=checked(session.execute_live({LiveOperationKind::preview,before,object({{"actor_id",V{actor}},{"kind",V{kind}},{"params",std::move(params)}})}));assert(same(before,result.source_identity)&&same(before,result.current_identity));return std::move(result.result);}
// 只按现行固定报价顺序构造独立期望，所有业务值仍来自真实旧preview叶。
A quotes(ResidentReplaySession& session,const V& views,const V& journey,const V& catalog){A result;const auto player=text(*views.find("command_context"),"actor_id");auto append=[&](const std::string& kind,V params=object({})){result.push_back(object({{"kind",V{kind}},{"actor_id",V{player}},{"params",params},{"result",preview(session,player,kind,std::move(params))}}));};
    for(auto kind:{"advance","pause_travel","resume_travel","travel_wait","return","rescue","wait"})append(kind);
    const auto& encounter=*journey.find("journey_encounter")->find("encounter");if(!encounter.as<D>()->empty())for(auto kind:{"encounter_talk","encounter_fight"})append(kind,object({{"encounter_id",*encounter.find("encounter_id")}}));
    const auto phase=text(*views.find("interaction_view"),"phase");if(phase=="action")append("dialogue_confirm");auto capabilities=boundary::strings(*catalog.find("data")->find("required_capabilities"),"capabilities");if((phase=="say"||phase=="choice")&&std::find(capabilities.begin(),capabilities.end(),"npc_society")!=capabilities.end())append("ask_news");if(phase!="scene"&&phase!="choice")append("end_interaction");return result;
}
// 取原固定frame所需人物顺序；self/peer/speaker去重，不以caller名单扩展到敌军或其它会话。
std::vector<std::string> people(const V& views,const V& journey){std::vector<std::string> ids{text(*views.find("command_context"),"actor_id")};auto append=[&](const std::string& id){if(!id.empty()&&std::find(ids.begin(),ids.end(),id)==ids.end())ids.push_back(id);};auto& encounter=*journey.find("journey_encounter")->find("encounter");if(!encounter.as<D>()->empty())append(text(encounter,"provider_actor_id"));auto& dialogue=*views.find("interaction_view");if(text(dialogue,"phase")!="scene")append(dialogue.find("speaker")?text(dialogue,"speaker"):text(*dialogue.find("context"),"provider_actor_id"));return ids;}
// 每个子DTO逐字值/类型/字段序一致，批次自身也不得增添快照、身份副本或任意人物字段。
V expected_frame(ResidentReplaySession& session,const V& catalog){D views;for(auto id:{"command_context","action_context","screen_context","hud_view","journey_input_need","interaction_view"})views.emplace_back(id,query(session,id));V view{std::move(views)};D journey;auto append=[&](const std::string& id){journey.emplace_back(id,query(session,id));};append("journey_location");append("journey_encounter");bool encounter=!journey.back().second.find("encounter")->as<D>()->empty();if(!encounter){append("journey_companions");append("journey_logistics");append("journey_travel");}append("journey_map_position");append("journey_route");append("journey_crossings");V travel{std::move(journey)};D characters;for(auto& id:people(view,travel)){auto character=query(session,"character_input",object({{"actor_id",V{id}}}));assert(character.as<D>()->size()==3&&character.find("actor_view")->as<D>()->size()==6&&character.find("appearance_view")->as<D>()->size()==5);characters.emplace_back(id,std::move(character));}auto quoted=quotes(session,view,travel,catalog);return object({{"ok",V{true}},{"views",std::move(view)},{"journey",std::move(travel)},{"characters",V{std::move(characters)}},{"quotes",V{std::move(quoted)}}});}
// 旧页、越权字段和可变结果都不能修改唯一world；拒绝优先级仍在原source外门。
void denied(ResidentReplaySession& session,const LiveOperation& op,const std::string& code){auto before=checked(session.checkpoint());auto world=checked(session.export_state());auto source=checked(session.identity());auto result=session.execute_live(op);assert(!result.ok&&result.error.original.code==code);assert(before==checked(session.checkpoint())&&same(source,checked(session.identity())));exact(world,checked(session.export_state()));}
// 只在原walker choice推进一次原选择并恢复；证明相同revision也不能接纳旧epoch批次。
void choice_epoch(ResidentReplaySession& session,const V& expected){auto saved=checked(session.checkpoint());auto source=checked(session.identity());auto context=query(session,"command_context");auto selected=object({{"kind",V{std::string{"dialogue_choose"}}},{"params",object({{"option_id",V{std::string{"ask"}}}})},{"actor_id",*context.find("actor_id")},{"request_seq",*context.find("next_request_seq")},{"expected_revision",V{source.revision}}});auto result=checked(session.execute_live({LiveOperationKind::command,source,std::move(selected)}));assert(boundary::get_bool(result.result,"ok","result"));denied(session,request(source,"player_frame_seed"),"StalePreview");require(session.restore(saved));assert(checked(session.identity()).execution_epoch>source.execution_epoch);denied(session,request(source,"player_frame_seed",object({{"actor_id",V{std::string{"actor.blackwater.commander"}}}})),"StaleWorld");exact(expected,query(session,"player_frame_seed"));}
}
// 三个既有原GD输入覆盖无会面、真实choice和两支NPC军团终态；不重复规模推进。
int main(int argc,char** argv){assert(argc==3);auto fixtures=read(argv[1]);std::string root=argv[2];Integer count=0;for(const auto& row:*fixtures.as<A>()){auto resolve=[&](const std::string& p){return p.front()=='/'?p:root+"/"+p;};auto catalog=read(resolve(text(row,"catalog")));auto state=read(resolve(text(row,"state")));auto session=create_resident_replay_session();require(session->initialize(catalog,state));auto checkpoint=checked(session->checkpoint());auto full=checked(session->export_state());auto source=checked(session->identity());auto expected=expected_frame(*session,catalog);auto actual=query(*session,"player_frame_seed");exact(expected,actual);assert(checkpoint==checked(session->checkpoint())&&same(source,checked(session->identity())));exact(full,checked(session->export_state()));
        for(auto name:{"actor_id","army_id","observer","queries"})denied(*session,request(source,"player_frame_seed",object({{name,V{std::string{"actor.blackwater.commander"}}}})),"UnsupportedResidentField");auto wrong=source;++wrong.tick;denied(*session,request(wrong,"player_frame_seed"),"StalePreview");
        auto& characters=*actual.find("characters")->as<D>();assert(!characters.empty());*characters.front().second.find("actor_view")->find("display_name")=V{std::string{"display-only mutation"}};actual.find("journey")->as<D>()->clear();exact(expected,query(*session,"player_frame_seed"));assert(checkpoint==checked(session->checkpoint()));if(text(*expected.find("views")->find("interaction_view"),"phase")=="choice")choice_epoch(*session,expected);++count;
    }assert(count==3);std::cout<<"background_player_frame_seed: PASS (3 actual sessions; exact ordered old leaf DTOs/quotes, encounter branch, selected public portraits, copy isolation, immutable world and revision/restore-epoch guards)\n";}
